
/* ===== IMPERIA: gra w iframe, multiplayer przez Firebase, nick i kolor z konta ===== */
const IMP_B64="";
function impAccInfo(){
  const u=(typeof ACC!=='undefined')?ACC.user:null;
  const nick=String((typeof ACC!=='undefined'&&ACC.nick)||(u&&u.displayName)||(u&&u.email?u.email.split('@')[0]:'')||'').replace(/[<>&]/g,'').trim().slice(0,16);
  const col=(typeof ACC!=='undefined'&&/^#[0-9a-f]{6}$/i.test(ACC.col||''))?ACC.col:'';
  return{logged:!!u,nick,col};
}
window.IMP_BRIDGE={db:()=>fbDB,ensureAuth:()=>onlineEnsureAuth(),fb:()=>firebase,acc:impAccInfo};
function impSig(){const a=impAccInfo(),u=(typeof ACC!=='undefined'&&ACC.user)?ACC.user.uid:'';return[u,a.nick,a.col].join('|')}
function impOpen(){
  const h=document.getElementById('hub');if(h)h.style.display='none';
  document.getElementById('imp').hidden=false;
  const f=document.getElementById('impFrame'),sig=impSig();
  if(f.dataset.loaded&&f.dataset.sig!==sig){ /* zmieniło się konto, nick lub kolor: załaduj grę od nowa */
    try{f.contentWindow.__impCleanup&&f.contentWindow.__impCleanup()}catch(e){}
    f.removeAttribute('srcdoc');delete f.dataset.loaded;
  }
  if(!f.dataset.loaded){
    const b=atob(IMP_B64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
    f.srcdoc=new TextDecoder('utf-8').decode(u);f.dataset.loaded='1';f.dataset.sig=sig;
  }
}
function impExit(){document.getElementById('imp').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}
/* ===== PRAWDZIWE ŻYCIE: gra 3D solo w iframe (three.js z CDN) ===== */
const RL_B64="";
function rlOpen(){
  const h=document.getElementById('hub');if(h)h.style.display='none';
  document.getElementById('rl').hidden=false;
  const f=document.getElementById('rlFrame');
  if(!f.dataset.loaded){
    const b=atob(RL_B64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
    f.addEventListener('load',()=>{try{f.contentWindow.focus()}catch(e){}});
    f.srcdoc=new TextDecoder('utf-8').decode(u);f.dataset.loaded='1';
  }else{try{f.contentWindow.focus()}catch(e){}}
}
function rlExit(){document.getElementById('rl').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}
const TTT_B64='';
function tttOpen(){const h=document.getElementById('hub');if(h)h.style.display='none';document.getElementById('ttt').hidden=false;const f=document.getElementById('tttFrame');if(!f.dataset.loaded){const b=atob(TTT_B64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);f.srcdoc=new TextDecoder('utf-8').decode(u);f.dataset.loaded='1'}}
function tttBridge(){return{db:fbDB,auth:onlineEnsureAuth,ts:firebase.database.ServerValue.TIMESTAMP,net:()=>!!(fbDB&&fbAuth),nick:()=>(typeof ACC!=='undefined'&&ACC.nick)||'',stats:tttStats}}
function tttStats(code,S,ms){
  if(!S||!S.win||!S.X||!S.O||!ms||!code)return;
  statsRecord('ttt_'+String(code).toLowerCase().replace(/[^a-z0-9]/g,'')+'_'+(S.rd||0),'ttt',S.win==='D'?'d':S.win===ms?'w':'l',[{uid:S.X,name:S.nX},{uid:S.O,name:S.nO}]);
}
function tttExit(){try{const f=document.getElementById('tttFrame');if(f&&f.contentWindow&&f.contentWindow.__tttLeave)f.contentWindow.__tttLeave()}catch(e){}document.getElementById('ttt').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}

const KULKI_B64='';
function kulkiOpen(){const h=document.getElementById('hub');if(h)h.style.display='none';document.getElementById('kul').hidden=false;const f=document.getElementById('kulFrame');if(!f.dataset.loaded){const b=atob(KULKI_B64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);f.srcdoc=new TextDecoder('utf-8').decode(u);f.dataset.loaded='1'}}
function kulkiBridge(){return{db:fbDB,auth:onlineEnsureAuth,ts:firebase.database.ServerValue.TIMESTAMP,net:()=>!!(fbDB&&fbAuth),nick:()=>(typeof ACC!=='undefined'&&ACC.nick)||'',stats:kulkiStats}}
function kulkiStats(code,gid,players,r){
  if(!code||!gid||!players||players.length<2||!(r==='w'||r==='l'||r==='d'))return;
  statsRecord('kulki_'+String(code).toLowerCase().replace(/[^a-z0-9]/g,'')+'_'+String(gid).toLowerCase().replace(/[^a-z0-9]/g,''),'kulki',r,players);
}
function kulkiExit(){try{const f=document.getElementById('kulFrame');if(f&&f.contentWindow&&f.contentWindow.__kulkiLeave)f.contentWindow.__kulkiLeave()}catch(e){}document.getElementById('kul').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}
